import json
from http import HTTPStatus

class StubClient:
    """Stands in for an HTTP client. No network is touched."""

    def __init__(self, routes):
        self.routes = routes
        self.requests = []

    def get(self, path):
        self.requests.append(("GET", path))
        return self.routes.get(path, (404, ""))

def find_user(client, user_id):
    status, body = client.get("/users/" + str(user_id))
    if status == 200:
        return json.loads(body)
    if status == 404:
        return None
    raise RuntimeError("unexpected " + str(status) + " " + HTTPStatus(status).phrase)

client = StubClient({"/users/1": (200, '{"name": "Ada"}'), "/users/2": (503, "")})
print(find_user(client, 1))
print(find_user(client, 9))
try:
    find_user(client, 2)
except RuntimeError as err:
    print(err)
print(client.requests)

script = iter([(503, ""), (200, "{}")]).__next__
print(script(), script())

