class FlakyClient:
    """Times out `failures` times, then answers. A stand-in for a bad network."""

    def __init__(self, failures, answer):
        self.failures = failures
        self.answer = answer
        self.calls = 0

    def get(self, path, timeout):
        self.calls += 1
        if self.calls <= self.failures:
            raise TimeoutError("no reply within " + str(timeout) + "s")
        return self.answer

def get_with_retry(client, path, attempts, sleep):
    for attempt in range(1, attempts + 1):
        try:
            return client.get(path, timeout=5)
        except (TimeoutError, ConnectionError):
            if attempt == attempts:
                raise
            sleep(min(8, 0.5 * 2 ** (attempt - 1)))

waits = []
client = FlakyClient(2, (200, '{"ok": true}'))
print(get_with_retry(client, "/health", 4, waits.append))
print(client.calls, waits)

try:
    get_with_retry(FlakyClient(9, (200, "")), "/health", 3, waits.append)
except TimeoutError as err:
    print("gave up:", err)

