import json

def fetch_json(request, attempts):
    for attempt in range(attempts):
        status, body = request()
        if status == 200:
            return json.loads(body)
        if status == 404:
            return None
        if status == 429 or 500 <= status <= 599:
            continue
        raise ValueError("request refused with status " + str(status))
    raise RuntimeError("gave up after " + str(attempts) + " attempts")

def wait_before(retry, base, cap, retry_after):
    if retry_after is not None and retry_after.isdigit():
        return int(retry_after)
    return min(cap, base * 2 ** (retry - 1))

def worth_retrying(method, status, has_key):
    transient = status is None or status == 429 or status in (500, 502, 503, 504)
    if not transient:
        return False
    repeatable = method in ("GET", "HEAD", "PUT", "DELETE", "OPTIONS")
    return repeatable or has_key

import json

def names_for(get, ids):
    names = []
    for user_id in ids:
        status, body = get("/users/" + str(user_id))
        if status == 404:
            continue
        if status != 200:
            raise RuntimeError("user " + str(user_id) + ": status " + str(status))
        names.append(json.loads(body)["name"])
    return names

import json

def parse_body(headers, body):
    if body == "":
        return None
    content_type = ""
    for name, value in headers.items():
        if name.lower() == "content-type":
            content_type = value
    if not content_type.startswith("application/json"):
        return body
    try:
        return json.loads(body)
    except json.JSONDecodeError as err:
        raise ValueError("malformed JSON body: " + str(err))

