import json

class FlakyClient:
    """Fails its first `failures` calls, then answers. No network is involved."""

    def __init__(self, failures, answer, error=TimeoutError):
        self.failures = failures
        self.answer = answer
        self.error = error
        self.calls = 0

    def get(self, path, timeout):
        self.calls += 1
        if self.calls <= self.failures:
            raise self.error("no reply within " + str(timeout) + "s")
        return self.answer

def get_json(client, path, attempts, sleep):
    for attempt in range(1, attempts + 1):
        try:
            status, body = client.get(path, timeout=5)
        except (TimeoutError, ConnectionError):
            if attempt == attempts:
                raise
            sleep(2 ** (attempt - 1))
            continue
        return json.loads(body)
